#include <vector>

class Solution {
public:
    int countMatchingSubarrays(std::vector<int>& nums, std::vector<int>& pattern) {
        auto sgn = [](int x) { return x > 0 ? 1 : (x < 0 ? -1 : 0); };
        std::vector<int> diff;
        for (size_t i = 0; i < nums.size() - 1; ++i) diff.push_back(sgn(nums[i + 1] - nums[i]));
        int m = pattern.size(), ans = 0;
        for (size_t i = 0; i + m <= diff.size(); ++i) {
            bool ok = true;
            for (int j = 0; j < m; ++j) {
                if (diff[i + j] != pattern[j]) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }
};

class Solution {
    public int countMatchingSubarrays(int[] nums, int[] pattern) {
        int n = nums.length;
        int[] diff = new int[n - 1];
        for (int i = 0; i < n - 1; ++i) {
            int d = nums[i + 1] - nums[i];
            diff[i] = d > 0 ? 1 : (d < 0 ? -1 : 0);
        }
        int m = pattern.length, ans = 0;
        for (int i = 0; i + m <= diff.length; ++i) {
            boolean ok = true;
            for (int j = 0; j < m; ++j) {
                if (diff[i + j] != pattern[j]) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }
}

